-- Tanyx Scripts | Loading Screen Engine
-- ====================================================================
local function _show_tanyx_loading()
    local y = typeof(getgenv) == "function" and getgenv() or _G;
    y.TanyxCanvasHold = true;
    local T = game:GetService("CoreGui");
    pcall(function()
        local t = gethui();
        if typeof(t) == "Instance" then T = t; end;
    end);
    local t = T:FindFirstChild("TanyxHubLoading");
    if t then t:Destroy(); end;

    local h = Instance.new("ScreenGui");
    h.Name = "TanyxHubLoading";
    h.ResetOnSpawn = false;
    h.IgnoreGuiInset = true;
    h.DisplayOrder = 1000;
    h.ZIndexBehavior = Enum.ZIndexBehavior.Sibling;

    local frame = Instance.new("Frame");
    frame.AnchorPoint = Vector2.new(0.5, 0);
    frame.Position = UDim2.new(0.5, 0, 0, 24);
    frame.Size = UDim2.fromOffset(280, 68);
    frame.BackgroundColor3 = Color3.fromRGB(15, 17, 26);
    frame.BackgroundTransparency = 0.05;
    frame.Parent = h;
    Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 10);

    local stroke = Instance.new("UIStroke", frame);
    stroke.Color = Color3.fromRGB(168, 85, 247);
    stroke.Thickness = 1.5;
    stroke.Transparency = 0.2;

    local title = Instance.new("TextLabel");
    title.BackgroundTransparency = 1;
    title.Position = UDim2.fromOffset(14, 8);
    title.Size = UDim2.new(1, -28, 0, 20);
    title.Font = Enum.Font.GothamBold;
    title.TextSize = 16;
    title.TextColor3 = Color3.fromRGB(243, 244, 246);
    title.TextXAlignment = Enum.TextXAlignment.Left;
    title.Text = "Tanyx Scripts";
    title.Parent = frame;

    local percent = Instance.new("TextLabel");
    percent.BackgroundTransparency = 1;
    percent.Position = UDim2.fromOffset(14, 8);
    percent.Size = UDim2.new(1, -28, 0, 20);
    percent.Font = Enum.Font.GothamBold;
    percent.TextSize = 16;
    percent.TextColor3 = Color3.fromRGB(56, 189, 248);
    percent.TextXAlignment = Enum.TextXAlignment.Right;
    percent.Text = "0%";
    percent.Parent = frame;

    local status = Instance.new("TextLabel");
    status.BackgroundTransparency = 1;
    status.Position = UDim2.fromOffset(14, 28);
    status.Size = UDim2.new(1, -28, 0, 14);
    status.Font = Enum.Font.GothamMedium;
    status.TextSize = 12;
    status.TextColor3 = Color3.fromRGB(148, 163, 184);
    status.TextXAlignment = Enum.TextXAlignment.Left;
    status.Text = "Initializing runtime...";
    status.Parent = frame;

    local barBg = Instance.new("Frame");
    barBg.Position = UDim2.fromOffset(14, 48);
    barBg.Size = UDim2.new(1, -28, 0, 8);
    barBg.BackgroundColor3 = Color3.fromRGB(30, 32, 48);
    barBg.Parent = frame;
    Instance.new("UICorner", barBg).CornerRadius = UDim.new(1, 0);

    local fill = Instance.new("Frame");
    fill.Size = UDim2.new(0, 0, 1, 0);
    fill.BackgroundColor3 = Color3.fromRGB(255, 255, 255);
    fill.Parent = barBg;
    Instance.new("UICorner", fill).CornerRadius = UDim.new(1, 0);

    local grad = Instance.new("UIGradient", fill);
    grad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(168, 85, 247)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(56, 189, 248))
    });

    pcall(function() h.Parent = T; end);

    local logPath = "TanyxLibrary/SAE_LoadProgress.txt";
    local function saveStep(D)
        pcall(function()
            if not isfolder("TanyxLibrary") then makefolder("TanyxLibrary"); end;
            writefile(logPath, tostring(D).." "..tostring(os.time()));
        end);
    end;
    saveStep(0);

    y.TanyxLoadStep = function(step)
        local D = math.clamp(math.floor(tonumber(step) or 0), 0, 10);
        saveStep(D);
        pcall(function()
            fill.Size = UDim2.new(D / 10, 0, 1, 0);
            percent.Text = tostring(D * 10).."%";
            status.Text = D >= 10 and "Ready" or ("Loading step " .. tostring(D + 1) .. " / 10");
        end);
        task.wait(0.02);
        if D >= 10 then
            y.TanyxLoadStep = nil;
            y.TanyxCanvasHold = nil;
            task.delay(0.6, function()
                pcall(function() h:Destroy(); end);
            end);
        end;
    end;
end;
pcall(_show_tanyx_loading);

